{"path":"contact.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Get in Touch — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Contact {{BUSINESS_NAME}} for upcoming sound baths, private sessions, and collaborations in {{CITY}}, {{STATE}}.">
  <style>
    :root{
      --bg:#F6EFE6; /* warm parchment */
      --earth:#8A5A44; /* terracotta */
      --accent:#3A6A57; /* deep moss */
      --muted:#7B6A59;
      --glass:rgba(255,255,255,0.6);
      --radius:14px;
      --max:1100px;
      font-family: Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial;
    }
    html,body{height:100%;background:linear-gradient(180deg,var(--bg),#efe9da);color:var(--earth);margin:0}
    body{display:flex;align-items:flex-start;justify-content:center;padding:32px 20px}
    .wrap{max-width:var(--max);width:100%;background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.5));border-radius:20px;box-shadow:0 10px 30px rgba(120,100,80,0.12);overflow:hidden;position:relative}
    /* patterned backdrop */
    .wrap::before{content:"";position:absolute;inset:0;opacity:0.12;background-image:url('assets/img/pattern.svg');background-repeat:repeat;background-size:240px}
    header{position:relative;z-index:2;padding:36px 40px 20px;display:flex;align-items:center;justify-content:space-between}
    nav a{color:var(--muted);text-decoration:none;margin-left:18px;font-weight:600}
    .brand{display:flex;align-items:center;gap:14px}
    .logo{width:52px;height:52px;border-radius:12px;background:linear-gradient(135deg,var(--earth),#c77d58);display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:28px;padding:20px 40px 40px;align-items:start;position:relative;z-index:2}
    .title{font-size:28px;line-height:1.05;margin:0 0 10px;font-weight:700}
    .subtitle{color:var(--muted);margin:0 0 18px}
    .contact-card{background:linear-gradient(180deg,rgba(255,255,255,0.85),rgba(255,255,255,0.7));border-radius:14px;padding:18px;box-shadow:0 6px 20px rgba(90,70,50,0.06)}
    form{display:flex;flex-direction:column;gap:12px}
    input,textarea,select{border:1px solid rgba(128,100,80,0.12);padding:12px 12px;border-radius:10px;font-size:14px}
    button.cta{background:linear-gradient(90deg,var(--accent),#2f6a56);color:#fff;border:0;padding:12px 14px;border-radius:10px;font-weight:700;cursor:pointer}
    .info{font-size:14px;color:var(--muted)}
    .panel{padding:20px}
    .section{margin-bottom:18px}
    h3{margin:0 0 8px;font-size:16px;color:var(--earth)}
    ul{margin:0;padding-left:18px;color:var(--muted)}
    .flow{background:linear-gradient(180deg,rgba(250,245,240,0.6),rgba(255,255,255,0.5));padding:16px;border-radius:10px}
    footer{padding:18px 40px;background:linear-gradient(180deg,rgba(255,255,255,0.4),transparent);display:flex;justify-content:space-between;align-items:center;font-size:13px;color:var(--muted)}
    @media(max-width:880px){
      .hero{grid-template-columns:1fr;}
      header{padding:22px}
      .wrap::before{background-size:160px}
    }
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div class="brand">
        <div class="logo">SB</div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div style="font-size:13px;color:var(--muted)">{{TAGLINE}}</div>
        </div>
      </div>
      <nav aria-label="Primary">
        <a href="index.html">Gatherings</a>
        <a href="private-sessions.html">Privates</a>
        <a href="pricing.html">Investment</a>
        <a href="about.html">About</a>
        <a href="faq.html">Questions</a>
        <a href="book.html">Book</a>
      </nav>
    </header>

    <main class="hero" role="main">
      <div>
        <h1 class="title">Reach out — arrange a ritual of sound</h1>
        <p class="subtitle">A warm invitation to join our communal sound baths, request a private 1:1 or corporate offering, or simply ask a question. We craft each session to hold space for deep listening and restoration.</p>

        <div class="section contact-card">
          <h3>How we can help</h3>
          <p class="info">Local gatherings at {{VENUE_NAME}} in {{CITY}} · Private sessions by request · Collaborations and pop-ups across {{STATE}}.</p>
          <div style="margin-top:12px;display:flex;gap:8px">
            <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a style="background:transparent;border:1px solid rgba(140,110,95,0.12);padding:10px 12px;border-radius:10px;text-decoration:none;color:var(--earth);font-weight:700" href="mailto:{{EMAIL}}">Email us</a>
          </div>
        </div>

        <div class="section" style="margin-top:18px">
          <h3>What to bring</h3>
          <p class="info">A yoga mat or blanket, a small pillow for the neck, layers to keep warm, and an open heart. We provide bolsters and straps on request — mention it in your message.</p>
        </div>

        <div class="section">
          <h3>Contraindications & gentle notes</h3>
          <p class="info">Sound bathing is deeply relaxing but may not be appropriate for everyone. Please consult with a physician if you are pregnant, have a pacemaker or implantable device, recent surgery, epilepsy, or are currently under psychiatric care. If you are taking medication that changes consciousness, please reach out before booking.</p>
        </div>

      </div>

      <aside class="panel">
        <div class="contact-card">
          <form id="contactForm" action="{{PRIMARY_CTA_URL}}" method="post">
            <label class="info">Your name</label>
            <input type="text" name="name" placeholder="Your full name" required>
            <label class="info">Email or phone</label>
            <input type="text" name="contact" placeholder="you@email.com or {{PHONE}}" required>
            <label class="info">Interested in</label>
            <select name="interest">
              <option>Next public event</option>
              <option>Private 1:1 session</option>
              <option>Couples session</option>
              <option>Corporate / team experience</option>
              <option>Venue collaboration</option>
            </select>
            <label class="info">Message</label>
            <textarea name="message" rows="4" placeholder="A note about dates, accessibility needs, or group size"></textarea>
            <div style="display:flex;gap:8px;margin-top:8px">
              <button type="submit" class="cta">Send request</button>
              <button type="button" onclick="location.href='mailto:{{EMAIL}}'" style="background:transparent;border:1px solid rgba(140,110,95,0.12);padding:10px 12px;border-radius:10px">Email</button>
            </div>
          </form>
        </div>

        <div style="margin-top:16px">
          <h3>Quick details</h3>
          <p class="info">Phone: <a href="tel:{{PHONE}}" style="color:var(--accent);text-decoration:none">{{PHONE}}</a><br>Email: <a href="mailto:{{EMAIL}}" style="color:var(--accent);text-decoration:none">{{EMAIL}}</a></p>
          <h3 style="margin-top:12px">Typical flow</h3>
          <div class="flow">
            <ol style="margin:0;padding-left:18px;color:var(--muted)">
              <li>Arrival & settling — soft tea, gentle orientation.</li>
              <li>Guided opening — intentional breath and short centering ritual.</li>
              <li>Sound immersion — instruments are played in a slow, layered arc (crystal bowls, gong, chimes, and tuned string resonance).</li>
              <li>Integration — a gentle re-emergence, optional sharing, and closing.</li>
            </ol>
          </div>
        </div>

        <div style="margin-top:16px">
          <h3>Finding us</h3>
          <p class="info">Most public events are at {{VENUE_NAME}} in {{CITY}}. Private offerings available online or at your space. Note travel fee may apply for distances beyond the metro.</p>
        </div>
      </aside>
    </main>

    <footer>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div class="info">Facilitator — {{FACILITATOR_NAME}} · Next session: {{NEXT_EVENT_DATE}}</div>
      </div>
      <div class="info">Made with care · Small groups · Conscious curation</div>
    </footer>
  </div>

  <script>
    (function(){
      const form=document.getElementById('contactForm');
      form.addEventListener('submit',function(e){
        // simple UX: prevent default to avoid actual navigation in static demo
        e.preventDefault();
        const data=new FormData(form);
        // assemble a friendly message for email fallback
        const body=[];
        for(const pair of data.entries()) body.push(encodeURIComponent(pair[0])+"="+encodeURIComponent(pair[1]));
        const url=form.action || ('mailto:{{EMAIL}}');
        // try fetch POST if action provided and looks like an endpoint
        if(url && url.startsWith('http')){
          fetch(url,{method:'POST',body:data}).then(()=>alert('Thanks — we received your request.')).catch(()=>alert('Request queued. We will respond soon.'));
        } else {
          // fallback: open mail client with form content
          const subject=encodeURIComponent('Inquiry from {{BUSINESS_NAME}} site');
          const bodyText=decodeURIComponent(body.join('\n'));
          window.location.href='mailto:{{EMAIL}}?subject='+subject+'&body='+encodeURIComponent(bodyText);
        }
      });
    })();
  </script>
</body>
</html>"} 
